from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/recommender_capstone_lab.json").read_text(
        encoding="utf-8"
    )
)

for role, rows in lab["roles"].items():
    cold = [r for r in rows if not r["train_count"] and r["positive"]]
    for row in cold:
        assert all(
            row["sources"][s] == row["sources"]["popularity"]
            for s in ["content", "user_cf"]
        )
    print(role, "cold positives", len(cold))
print("source cases", lab["samples"])

import hashlib
import json

first = {"schema": "বাংলা", "weights": [1, 2]}
second = {"weights": [1, 2], "schema": "বাংলা"}


def canonical(value):
    return (
        json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        + "\n"
    ).encode("utf-8")


first_bytes, second_bytes = canonical(first), canonical(second)
float_version = {"schema": "বাংলা", "weights": [1.0, 2.0]}
same_hash = (
    hashlib.sha256(first_bytes).digest() == hashlib.sha256(second_bytes).digest()
)
print(
    int(json.dumps(first) != json.dumps(second)),
    int(same_hash),
    int(canonical(float_version) != first_bytes),
    int(first_bytes[:-1] != first_bytes),
)

Model এক থাকলেও User নতুন কোনো সিনেমা দেখামাত্র তার **Seen History** বদলে যায়—তাই Cache Key-তে **History Fingerprint** না থাকলে দেখা সিনেমাটিই আবার সাজেশনে চলে আসে!

```python
def guarded_lookup(cache, key, expected_sig, compute_fn):
    entry = cache.get(key)
    if entry is not None and entry["sig"] == expected_sig:
        return entry["recs"], "HIT"
    recs = compute_fn()
    cache[key] = {"sig": expected_sig, "recs": recs}
    return recs, ("REJECT_RECOMPUTE" if entry is not None else "MISS")

cache = {}
r1, s1 = guarded_lookup(cache, ("u1", "v1"), ("u1", "v1", (1,)), lambda: [10, 20])
r2, s2 = guarded_lookup(cache, ("u1", "v1"), ("u1", "v1", (1, 10)), lambda: [20, 30])
print(f"Req1: {r1} ({s1}) | Req2 after watching 10: {r2} ({s2})")
```

> **উদাহরণ:** শুরুতে `user 1`-এর দেখা সেট ছিল $H_1 = \{1\}$ এবং Cache-এ ছিল `[10, 20]`। User `10` নম্বর সিনেমাটি দেখে ফেলায় নতুন সেট হলো $H'_1 = \{1, 10\}$। দুর্বল `("u1", "v1")` key পুরোনো এন্ট্রিতে হিট করলেও নিচের কোড ও উপরের **Payload Signature Guard** অমিল ধরে সাথে সাথে তা প্রত্যাখ্যান করে নতুন তালিকা `[20, 30]` নিশ্চিত করে।
